<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
Auth::requireLogin();
$pdo=Database::connection();ensure_member_soft_delete_schema($pdo);$year=(int)date('Y');
if(!isset($_SESSION['batch_member_ids'])||!is_array($_SESSION['batch_member_ids']))$_SESSION['batch_member_ids']=[];
$selected=array_values(array_unique(array_map('intval',$_SESSION['batch_member_ids'])));$message='';$error='';
function batch_audit(PDO $pdo,string $action,array $ids,array $details=[]):void{$pdo->prepare('INSERT INTO audit_log (admin_id,action,entity_type,details) VALUES (:admin,:action,"member",:details)')->execute(['admin'=>(int)($_SESSION['admin_id']??0)?:null,'action'=>$action,'details'=>json_encode(['member_ids'=>$ids]+$details,JSON_UNESCAPED_UNICODE)]);}
function ensure_batch_tag(PDO $pdo,string $name):int{$name=trim($name);if($name==='')return 0;$s=$pdo->prepare('SELECT id FROM tags WHERE LOWER(name)=LOWER(:n) LIMIT 1');$s->execute(['n'=>$name]);$id=(int)($s->fetchColumn()?:0);if(!$id){$pdo->prepare('INSERT INTO tags(name) VALUES(:n)')->execute(['n'=>$name]);$id=(int)$pdo->lastInsertId();}return $id;}
function ensure_membership(PDO $pdo,int $id,int $year):void{$m=$pdo->prepare('SELECT member_type FROM members WHERE id=:id');$m->execute(['id'=>$id]);$type=(string)($m->fetchColumn()?:'supporting');$pdo->prepare('INSERT IGNORE INTO memberships(member_id,membership_year,membership_type,payment_status,free_flight_entitled) VALUES(:id,:year,:type,"unpaid",1)')->execute(['id'=>$id,'year'=>$year,'type'=>$type]);}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');try{if($action==='sync_selection'){$visible=array_values(array_unique(array_map('intval',$_POST['visible_ids']??[])));$checked=array_values(array_unique(array_map('intval',$_POST['selected_ids']??[])));$selected=array_values(array_diff($selected,$visible));$selected=array_values(array_unique(array_merge($selected,$checked)));$_SESSION['batch_member_ids']=$selected;$message='Selectie bijgewerkt.';}elseif($action==='clear_selection'){$_SESSION['batch_member_ids']=[];$selected=[];$message='Selectie leeggemaakt.';}elseif($action==='apply'){if(!$selected)throw new RuntimeException('Selecteer eerst minstens één lid.');$ph=implode(',',array_fill(0,count($selected),'?'));$st=$pdo->prepare("SELECT id FROM members WHERE deleted_at IS NULL AND id IN ($ph)");$st->execute($selected);$ids=array_map('intval',array_column($st->fetchAll(),'id'));if(!$ids)throw new RuntimeException('Geen geldige actieve leden meer in de selectie.');$pdo->beginTransaction();$changes=[];if(isset($_POST['do_member_since'])){$v=trim((string)($_POST['member_since']??''));if($v==='')throw new RuntimeException('Vul een geldige datum in voor Lid sinds.');$s=$pdo->prepare('UPDATE members SET member_since=:v WHERE id=:id');foreach($ids as$id)$s->execute(['v'=>$v,'id'=>$id]);$changes['member_since']=$v;}if(isset($_POST['do_member_type'])){$v=in_array($_POST['member_type']??'', ['supporting','flying'],true)?(string)$_POST['member_type']:'';if(!$v)throw new RuntimeException('Ongeldig type lid.');$s=$pdo->prepare('UPDATE members SET member_type=:v WHERE id=:id');foreach($ids as$id){$s->execute(['v'=>$v,'id'=>$id]);ensure_membership($pdo,$id,$year);$pdo->prepare('UPDATE memberships SET membership_type=:v WHERE member_id=:id AND membership_year=:y')->execute(['v'=>$v,'id'=>$id,'y'=>$year]);}$changes['member_type']=$v;}if(isset($_POST['do_status'])){$v=in_array($_POST['status']??'', ['active','inactive'],true)?(string)$_POST['status']:'';if(!$v)throw new RuntimeException('Ongeldige status.');$s=$pdo->prepare('UPDATE members SET status=:v WHERE id=:id');foreach($ids as$id)$s->execute(['v'=>$v,'id'=>$id]);$changes['status']=$v;}if(isset($_POST['do_email'])){$v=strtolower(trim((string)($_POST['email']??'')));if($v===''||!filter_var($v,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Vul een geldig e-mailadres in.');$s=$pdo->prepare('UPDATE members SET email=:v WHERE id=:id AND (email IS NULL OR email="")');foreach($ids as$id)$s->execute(['v'=>$v,'id'=>$id]);$changes['email_if_empty']=$v;}if(isset($_POST['do_payment'])){$v=($_POST['payment_status']??'')==='paid'?'paid':'unpaid';foreach($ids as$id){ensure_membership($pdo,$id,$year);$pdo->prepare('UPDATE memberships SET payment_status=:v,paid_at=:p WHERE member_id=:id AND membership_year=:y')->execute(['v'=>$v,'p'=>$v==='paid'?date('Y-m-d'):null,'id'=>$id,'y'=>$year]);}$changes['payment_status']=$v;}if(isset($_POST['do_flight_right'])){$v=(int)(($_POST['free_flight_entitled']??'0')==='1');foreach($ids as$id){ensure_membership($pdo,$id,$year);$pdo->prepare('UPDATE memberships SET free_flight_entitled=:v WHERE member_id=:id AND membership_year=:y')->execute(['v'=>$v,'id'=>$id,'y'=>$year]);}$changes['free_flight_entitled']=$v;}if(isset($_POST['do_flight_date'])){$v=trim((string)($_POST['free_flight_date']??''));$v=$v!==''?$v:null;foreach($ids as$id){ensure_membership($pdo,$id,$year);$pdo->prepare('UPDATE memberships SET free_flight_date=:v WHERE member_id=:id AND membership_year=:y')->execute(['v'=>$v,'id'=>$id,'y'=>$year]);}$changes['free_flight_date']=$v;}if(isset($_POST['do_add_tag'])){$tag=trim((string)($_POST['add_tag']??''));if($tag==='')throw new RuntimeException('Vul een tag in om toe te voegen.');$tagId=ensure_batch_tag($pdo,$tag);$s=$pdo->prepare('INSERT IGNORE INTO member_tags(member_id,tag_id) VALUES(:m,:t)');foreach($ids as$id)$s->execute(['m'=>$id,'t'=>$tagId]);$changes['tag_added']=$tag;}if(isset($_POST['do_remove_tag'])){$tagId=(int)($_POST['remove_tag_id']??0);if($tagId<=0)throw new RuntimeException('Kies een tag om te verwijderen.');$s=$pdo->prepare('DELETE FROM member_tags WHERE member_id=:m AND tag_id=:t');foreach($ids as$id)$s->execute(['m'=>$id,'t'=>$tagId]);$changes['tag_removed_id']=$tagId;}if(isset($_POST['do_notes_append'])){$v=trim((string)($_POST['notes_append']??''));if($v==='')throw new RuntimeException('Vul notitietekst in.');$s=$pdo->prepare('UPDATE members SET notes=TRIM(CONCAT(COALESCE(notes,""),CASE WHEN notes IS NULL OR notes="" THEN "" ELSE "\n\n" END,:v)) WHERE id=:id');foreach($ids as$id)$s->execute(['v'=>$v,'id'=>$id]);$changes['notes_appended']=$v;}if(!$changes)throw new RuntimeException('Vink minstens één batchwijziging aan.');batch_audit($pdo,'batch_update',$ids,$changes);$pdo->commit();$message=count($ids).' leden aangepast.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$q=trim((string)($_GET['q']??''));$type=(string)($_GET['type']??'');$status=(string)($_GET['status']??'');$payment=(string)($_GET['payment']??'');$tagId=(int)($_GET['tag']??0);$flight=(string)($_GET['flight']??'');$where=['m.deleted_at IS NULL'];$params=['year'=>$year];if($q!==''){$where[]='(m.first_name LIKE :q OR m.last_name LIKE :q OR m.member_number LIKE :q OR m.email LIKE :q OR m.mobile LIKE :q)';$params['q']='%'.$q.'%';}if(in_array($type,['supporting','flying'],true)){$where[]='m.member_type=:type';$params['type']=$type;}if(in_array($status,['active','inactive'],true)){$where[]='m.status=:status';$params['status']=$status;}if(in_array($payment,['paid','unpaid'],true)){$where[]="COALESCE(ms.payment_status,'unpaid')=:payment";$params['payment']=$payment;}if($tagId>0){$where[]='EXISTS(SELECT 1 FROM member_tags z WHERE z.member_id=m.id AND z.tag_id=:tag)';$params['tag']=$tagId;}if(in_array($flight,['yes','no'],true))$where[]=$flight==='yes'?'COALESCE(ms.free_flight_entitled,1)=1':'COALESCE(ms.free_flight_entitled,1)=0';$sql='SELECT m.*,ms.payment_status,ms.free_flight_entitled,ms.free_flight_date,GROUP_CONCAT(DISTINCT t.name ORDER BY t.name SEPARATOR ", ") tag_names FROM members m LEFT JOIN memberships ms ON ms.member_id=m.id AND ms.membership_year=:year LEFT JOIN member_tags mt ON mt.member_id=m.id LEFT JOIN tags t ON t.id=mt.tag_id WHERE '.implode(' AND ',$where).' GROUP BY m.id ORDER BY m.last_name,m.first_name';$st=$pdo->prepare($sql);$st->execute($params);$members=$st->fetchAll();$tags=$pdo->query('SELECT id,name FROM tags ORDER BY name')->fetchAll();if($selected){$ph=implode(',',array_fill(0,count($selected),'?'));$s=$pdo->prepare("SELECT id,member_number,first_name,last_name FROM members WHERE deleted_at IS NULL AND id IN ($ph) ORDER BY last_name,first_name");$s->execute($selected);$selectedMembers=$s->fetchAll();$selected=array_map('intval',array_column($selectedMembers,'id'));$_SESSION['batch_member_ids']=$selected;}else$selectedMembers=[];$selectedMap=array_fill_keys($selected,true);
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tags & batchacties - Heli One</title><style>body{font-family:Arial,sans-serif;background:#f5f6f8;margin:0;color:#171717}header{background:#111;color:#fff;padding:18px 28px;display:flex;justify-content:space-between}header a{color:#fff}main{max-width:1400px;margin:32px auto;padding:0 22px}.top,.bar{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.btn{padding:10px 14px;border:0;border-radius:9px;background:#111;color:#fff;text-decoration:none;cursor:pointer;font-weight:700}.secondary{background:#e7eaee;color:#111}.muted{color:#69707a}.ok,.err{padding:12px 14px;border-radius:9px;margin:14px 0}.ok{background:#e9f8ee}.err{background:#feecec}.filters,.batch,.selectedbox{background:#fff;border-radius:14px;padding:18px;box-shadow:0 4px 18px #0000000d;margin:18px 0}.filters{display:grid;grid-template-columns:2fr repeat(5,1fr) auto auto;gap:10px}.filters input,.filters select,.batch input,.batch select,.batch textarea{padding:10px;border:1px solid #d6dbe1;border-radius:8px;width:100%;box-sizing:border-box}.tablewrap{overflow:auto;background:#fff;border-radius:14px;box-shadow:0 4px 18px #0000000d}table{border-collapse:collapse;width:100%;min-width:1100px}th,td{padding:12px;border-bottom:1px solid #eceff2;text-align:left;vertical-align:middle}th{background:#fafbfc;font-size:13px;color:#68707a}.selectedrow{background:#f2f8ff}.selectionactions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:12px 0}.batchgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px 18px}.op{border:1px solid #e2e6ea;border-radius:10px;padding:12px}.op label:first-child{font-weight:700;display:flex;gap:8px;align-items:center;margin-bottom:8px}.chips{display:flex;gap:7px;flex-wrap:wrap}.chip{background:#eef1f4;border-radius:999px;padding:6px 9px;font-size:13px}@media(max-width:950px){.filters{grid-template-columns:1fr 1fr}.batchgrid{grid-template-columns:1fr}}@media(max-width:560px){.filters{grid-template-columns:1fr}}</style></head><body><header><strong>Heli One Members</strong><div><a href="/">Dashboard</a> · <a href="/members.php">Leden</a> · <a href="/logout.php">Afmelden</a></div></header><main><div class="top"><div><h1>Tags & batchacties</h1><p class="muted">Zoek meerdere keren en bouw stap voor stap één blijvende selectie op.</p></div><a class="btn secondary" href="/members.php">← Leden</a></div><?php if($message):?><div class="ok"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="err"><?=e($error)?></div><?php endif;?><div class="selectedbox"><div class="bar"><div><strong><?=count($selected)?> lid/leden geselecteerd</strong><div class="muted">Je selectie blijft behouden terwijl je opnieuw zoekt of filtert.</div></div><?php if($selected):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="btn secondary" name="action" value="clear_selection">Selectie wissen</button></form><?php endif;?></div><?php if($selectedMembers):?><div class="chips" style="margin-top:12px"><?php foreach($selectedMembers as$m):?><span class="chip"><?=e($m['last_name'].' '.$m['first_name'])?> · <?=e($m['member_number']??'')?></span><?php endforeach;?></div><?php endif;?></div><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Zoek naam, lidnummer, e-mail of GSM"><select name="type"><option value="">Alle types</option><option value="supporting" <?=$type==='supporting'?'selected':''?>>Steunend</option><option value="flying" <?=$type==='flying'?'selected':''?>>Vliegend</option></select><select name="status"><option value="">Alle statussen</option><option value="active" <?=$status==='active'?'selected':''?>>Actief</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>Inactief</option></select><select name="payment"><option value="">Alle betalingen</option><option value="paid" <?=$payment==='paid'?'selected':''?>>Betaald</option><option value="unpaid" <?=$payment==='unpaid'?'selected':''?>>Niet betaald</option></select><select name="flight"><option value="">Vlucht: alles</option><option value="yes" <?=$flight==='yes'?'selected':''?>>Recht op vlucht</option><option value="no" <?=$flight==='no'?'selected':''?>>Geen recht</option></select><select name="tag"><option value="0">Alle tags</option><?php foreach($tags as$t):?><option value="<?=$t['id']?>" <?=$tagId===(int)$t['id']?'selected':''?>><?=e($t['name'])?></option><?php endforeach;?></select><button class="btn">Zoeken</button><a class="btn secondary" href="/batch.php">Wis filters</a></form><form method="post" id="selectionForm"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="sync_selection"><?php foreach($members as$m):?><input type="hidden" name="visible_ids[]" value="<?=(int)$m['id']?>"><?php endforeach;?><div class="selectionactions"><label><input type="checkbox" id="selectAll"> Selecteer alle huidige resultaten</label><button class="btn" type="submit">Selectie bijwerken</button><span class="muted"><?=count($members)?> huidige resultaten</span></div><div class="tablewrap"><table><thead><tr><th></th><th>Lid</th><th>Type</th><th>Status</th><th>E-mail</th><th>Betaling <?=$year?></th><th>Vlucht</th><th>Tags</th></tr></thead><tbody><?php if(!$members):?><tr><td colspan="8">Geen resultaten.</td></tr><?php endif;?><?php foreach($members as$m):$sel=isset($selectedMap[(int)$m['id']]);?><tr class="<?=$sel?'selectedrow':''?>"><td><input class="rowcheck" type="checkbox" name="selected_ids[]" value="<?=(int)$m['id']?>" <?=$sel?'checked':''?>></td><td><strong><?=e($m['last_name'].' '.$m['first_name'])?></strong><div class="muted"><?=e($m['member_number']??'')?></div></td><td><?=$m['member_type']==='flying'?'Vliegend':'Steunend'?></td><td><?=$m['status']==='active'?'Actief':'Inactief'?></td><td><?=e($m['email']??'')?></td><td><?=($m['payment_status']??'unpaid')==='paid'?'Betaald':'Niet betaald'?></td><td><?=(int)($m['free_flight_entitled']??1)===1?'Ja':'Nee'?></td><td><?=e($m['tag_names']??'')?></td></tr><?php endforeach;?></tbody></table></div></form><div class="batch"><h2>Batchwijzigingen voor <?=count($selected)?> geselecteerde leden</h2><p class="muted">Alleen aangevinkte acties worden uitgevoerd. Niet-aangevinkte velden blijven onaangeroerd.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="apply"><div class="batchgrid"><div class="op"><label><input type="checkbox" name="do_flight_right"> Recht op gratis vlucht <?=$year?></label><select name="free_flight_entitled"><option value="1">Recht geven</option><option value="0">Recht wegnemen</option></select></div><div class="op"><label><input type="checkbox" name="do_payment"> Betaling <?=$year?></label><select name="payment_status"><option value="paid">Betaald</option><option value="unpaid">Niet betaald</option></select></div><div class="op"><label><input type="checkbox" name="do_add_tag"> Tag toevoegen</label><input name="add_tag" list="taglist" placeholder="Naam van tag"></div><div class="op"><label><input type="checkbox" name="do_remove_tag"> Tag verwijderen</label><select name="remove_tag_id"><option value="0">Kies tag</option><?php foreach($tags as$t):?><option value="<?=$t['id']?>"><?=e($t['name'])?></option><?php endforeach;?></select></div><div class="op"><label><input type="checkbox" name="do_member_since"> Lid sinds aanpassen</label><input type="date" name="member_since"></div><div class="op"><label><input type="checkbox" name="do_email"> E-mailadres toevoegen indien leeg</label><input type="email" name="email" placeholder="bv. contact@bedrijf.be"></div><div class="op"><label><input type="checkbox" name="do_member_type"> Type lid aanpassen</label><select name="member_type"><option value="supporting">Steunend</option><option value="flying">Vliegend</option></select></div><div class="op"><label><input type="checkbox" name="do_status"> Status aanpassen</label><select name="status"><option value="active">Actief</option><option value="inactive">Inactief</option></select></div><div class="op"><label><input type="checkbox" name="do_flight_date"> Datum gratis vlucht</label><input type="date" name="free_flight_date"><div class="muted">Leeg laten + aanvinken wist de datum.</div></div><div class="op"><label><input type="checkbox" name="do_notes_append"> Notitie toevoegen</label><textarea name="notes_append" rows="3" placeholder="Wordt toegevoegd aan bestaande notities"></textarea></div></div><datalist id="taglist"><?php foreach($tags as$t):?><option value="<?=e($t['name'])?>"><?php endforeach;?></datalist><div style="margin-top:16px"><button class="btn" type="submit" <?=$selected?'':'disabled'?>>Wijzigingen toepassen op selectie</button></div></form></div></main><script>const all=document.getElementById('selectAll'),checks=[...document.querySelectorAll('.rowcheck')];function syncAll(){all.checked=checks.length>0&&checks.every(x=>x.checked);all.indeterminate=checks.some(x=>x.checked)&&!all.checked}all?.addEventListener('change',()=>checks.forEach(x=>x.checked=all.checked));checks.forEach(x=>x.addEventListener('change',syncAll));syncAll();</script></body></html>